package main
import("os";"strings";"testing")
func readAlphaContractFile(t *testing.T,path string)string{t.Helper();raw,err:=os.ReadFile(path);if err!=nil{t.Fatal(err)};return string(raw)}
func TestI18nFoundationSupportsEnglishAndChinese(t *testing.T){s:=readAlphaContractFile(t,"web/i18n.js");for _,want:=range []string{"sentinel.locale","zh-CN","English","中文","sentinel:localechange","supportedLocales","data-i18n","localStorage","Why this result","Continue →"}{if !strings.Contains(s,want){t.Fatalf("i18n missing %q",want)}};for _,bad:=range []string{"innerHTML","eval(","new Function","document.write"}{if strings.Contains(s,bad){t.Fatalf("unsafe i18n %q",bad)}}}
func TestAuxiliaryNavigationExposesLanguageAndAlpha(t *testing.T){s:=readAlphaContractFile(t,"web/aux-navigation.js");for _,want:=range []string{"/i18n.js","/alpha-center.html","sentinel-language-switcher","zh-CN","Alpha","nav.alpha","Sentinel 2.4 · AUX"}{if !strings.Contains(s,want){t.Fatalf("aux navigation missing %q",want)}};for _,retired:=range []string{"/easy.html","/scan-center.html","/security-center.html"}{if strings.Contains(s,retired){t.Fatalf("aux navigation links retired %q",retired)}}}
func TestAlphaCenterIsReadOnlyCapabilitySurface(t *testing.T){all:=readAlphaContractFile(t,"web/alpha-center.html")+"\n"+readAlphaContractFile(t,"web/alpha-center.js");for _,want:=range []string{"/api/readiness","/api/visibility","/api/quick-check","/api/actions/vault/isolation","UNDERSTAND","INVESTIGATE","CONTROL","RECOVER","LOCALIZATION","Alpha Capability Center"}{if !strings.Contains(all,want){t.Fatalf("Alpha missing %q",want)}};for _,bad:=range []string{"innerHTML","eval(","new Function","document.write","/api/actions/execute","/api/trust/capture","/api/changes/start","sudo "}{if strings.Contains(all,bad){t.Fatalf("Alpha contains unsafe %q",bad)}}}
func TestProductSnapshotReplacesRetiredEasyPortal(t *testing.T){html:=readAlphaContractFile(t,"web/index.html");js:=requireProductScript(t,"web/app/lenses/orient-investigate.js");for _,want:=range []string{"Sentinel 2.6","renderSnapshot","/api/quick-check","/api/review-queue","Attention index","Review queue"}{if !strings.Contains(html+js,want){t.Fatalf("snapshot missing %q",want)}};for _,bad:=range []string{"/api/actions/execute","/api/trust/capture","/api/changes/start","sudo "}{if strings.Contains(js,bad){t.Fatalf("read-only module contains mutation %q",bad)}}}